CREATE DATABASE IF NOT EXISTS demo;
USE demo;
CREATE TABLE IF NOT EXISTS greetings (id INT PRIMARY KEY AUTO_INCREMENT, message VARCHAR(100) NOT NULL);
INSERT INTO greetings (message) VALUES ('Hallo, Welt!');
SELECT message FROM greetings;

