import { MongoClient } from "mongodb";

const client = new MongoClient(process.env.MONGODB_URI ?? "mongodb://127.0.0.1:27017");
await client.connect();
const collection = client.db("demo").collection("greetings");
await collection.insertOne({ message: "Hallo, Welt!" });
console.log(await collection.findOne({ message: "Hallo, Welt!" }));
await client.close();
